import java.lang.annotation.*;
import java.time.*;
import java.util.*;

import jakarta.validation.*;
import jakarta.validation.constraints.*;

public class Main {
    public static class HariKerjaValidator implements ConstraintValidator<HariKerja, LocalDate> {
        @Override
        public boolean isValid(LocalDate tanggal, ConstraintValidatorContext ctx) {
            if (tanggal == null) {
                return true;
            }
            DayOfWeek hari = tanggal.getDayOfWeek();
            return hari != DayOfWeek.SATURDAY && hari != DayOfWeek.SUNDAY;
        }
    }

    static final Validator VALIDATOR = Validation.buildDefaultValidatorFactory().getValidator();

    static void periksa(Object o) {
        List<String> pesan = new ArrayList<>();
        for (ConstraintViolation<Object> v : VALIDATOR.validate(o)) {
            pesan.add(v.getPropertyPath() + ": " + v.getMessage());
        }
        Collections.sort(pesan);
        if (pesan.isEmpty()) {
            System.out.println("Valid");
        }
        for (String p : pesan) {
            System.out.println(p);
        }
    }

    public static void main(String[] args) {
        periksa(new Rapat("Evaluasi bulanan", LocalDate.of(2026, 11, 14)));
    }
}

class Rapat {
    @NotBlank
    String topik;

    @HariKerja
    LocalDate tanggal;

    Rapat(String topik, LocalDate tanggal) {
        this.topik = topik;
        this.tanggal = tanggal;
    }
}

