import java.lang.annotation.*;
import java.util.*;

import jakarta.validation.*;
import jakarta.validation.constraints.*;

public class Main {
    public static class NomorHpValidator implements ConstraintValidator<NomorHp, String> {
        @Override
        public boolean isValid(String nilai, ConstraintValidatorContext ctx) {
            if (nilai == null) {
                return true;
            }
            if (!nilai.startsWith("08") || nilai.length() < 10 || nilai.length() > 13) {
                return false;
            }
            for (char c : nilai.toCharArray()) {
                if (!Character.isDigit(c)) {
                    return false;
                }
            }
            return true;
        }
    }

    static final Validator VALIDATOR = Validation.buildDefaultValidatorFactory().getValidator();

    static void periksa(Object o) {
        List<String> pesan = new ArrayList<>();
        for (ConstraintViolation<Object> v : VALIDATOR.validate(o)) {
            pesan.add(v.getPropertyPath() + ": " + v.getMessage());
        }
        Collections.sort(pesan);
        if (pesan.isEmpty()) {
            System.out.println("Valid");
        }
        for (String p : pesan) {
            System.out.println(p);
        }
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        while (in.hasNextLine()) {
            String hp = in.nextLine();
            System.out.println(hp + ":");
            periksa(new Kontak(hp));
        }
    }
}

class Kontak {
    @NomorHp
    String hp;

    Kontak(String hp) {
        this.hp = hp;
    }
}

